// `Env` is generated by `npm run types` into worker-configuration.d.ts as a global interface.
// Secrets are not in wrangler.jsonc, so they are declared here and merged into it.
// Set them in `.dev.vars` locally, or with `wrangler secret put` for the deployed Worker.
declare global {
	interface Env {
		/** Guards the admin and dispatch routes. */
		ADMIN_TOKEN?: string;
		/** Only needed when LLM="anthropic". */
		ANTHROPIC_API_KEY?: string;
		// The LLM port (ports/llm.ts) is provider-neutral. These are all optional: which ones are
		// read depends on the `LLM` variable.
		/** A key for whichever provider `LLM` names. Checked before the provider-specific names below. */
		LLM_API_KEY?: string;
		OPENAI_API_KEY?: string;
		GEMINI_API_KEY?: string;
		OPENROUTER_API_KEY?: string;
		GROQ_API_KEY?: string;
		CLOUDFLARE_API_TOKEN?: string;
		/** Overrides the provider's base URL (for a gateway or proxy), or supplies it for LLM="openai-compatible". */
		LLM_BASE_URL?: string;
		LLM_MAX_TOKENS?: string;
		/** Reasoning effort, passed through to providers that support it. */
		LLM_EFFORT?: string;
	}
}

export type { Env };

type Env = globalThis.Env;
